    // In current YouTube layout, video items can be yt-lockup-view-model or ytd-rich-item-renderer
    const elements = Array.from(document.querySelectorAll('.yt-lockup-view-model, ytd-rich-item-renderer, ytd-grid-video-renderer'));
    for (const el of elements) {
      const link = el.querySelector('a[href*="/watch?v="]');
      if (!link) continue;
      const href = link.href.split('&')[0];
      if (seen.has(href)) continue;

      // Let's extract title
      let title = "";
      const titleEl = el.querySelector('.yt-lockup-metadata-view-model-wiz__title, #video-title, h3 a, a.ytLockupMetadataViewModelTitle');
      if (titleEl) {
        title = titleEl.innerText.trim();
      }
      if (!title) {
        // Look for any anchor with text
        const textAnchors = Array.from(el.querySelectorAll('a')).map(a => a.innerText.trim()).filter(t => t.length > 5 && !/^\d+:\d+$/.test(t));
        if (textAnchors.length > 0) title = textAnchors[0];
      }

      // Extract metadata (views, time ago)
      const textLines = el.innerText.split('\n').map(t => t.trim()).filter(Boolean);
      const meta = textLines.filter(t => t.includes('ago') || t.includes('views') || t.includes('Streamed')).join(' • ');

      if (title && href) {
        seen.add(href);
        list.push({ title, href, meta, rawLines: textLines });
      }
    }
    return {
      channelTitle: document.title.replace(" - YouTube", "").trim(),
      videos: list
    };
  });
}

